const entrada = $input.first().json || {};
const normalizado = String(entrada.mensagem || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toLowerCase();
const edicao = /(?:editar|alterar|atualizar|corrigir|mudar).*(?:cadastro|empresa|negocio|servico|dados)|(?:meu cadastro|meus dados)/.test(normalizado);
const cadastro = /(?:me cadastrar|fazer (?:um )?cadastro|criar (?:um )?cadastro|participar da elo|entrar (?:na|para a) elo)|(?:quero|gostaria|preciso|desejo|como|onde|posso).*cadastr/.test(normalizado);
if (!edicao && !cadastro) return [{ json: { handled: false, cliente_id: entrada.cadastro_id || null } }];

const appBase = String($env.N8N_ELO_FRONTEND_URL || 'http://127.0.0.1:5173').replace(/\/+$/, '');
const baseChatwoot = String($env.N8N_CHATWOOT_BASE_URL_Elo || '').replace(/\/+$/, '');
const chatwootToken = String($env.N8N_CHATWOOT_API_TOKEN_Elo || '');
if (!baseChatwoot || !chatwootToken) throw new Error('Variáveis do Chatwoot da Elo não configuradas no n8n.');

const resposta = edicao
  ? `Para editar seu cadastro com segurança, acesse a área do participante: ${appBase}/entrar`
  : `Para criar seu cadastro na Elo, preencha o formulário seguro: ${appBase}/cadastro`;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${baseChatwoot}/api/v1/accounts/${entrada.account_id}/conversations/${entrada.conversation_id}/messages`,
  headers: { api_access_token: chatwootToken, 'Content-Type': 'application/json' },
  json: true,
  body: { content: resposta, message_type: 'outgoing', private: false, content_type: 'text' },
});

return [{ json: { handled: true, cadastro_id: entrada.cadastro_id || null, acao: edicao ? 'redirecionar_edicao' : 'redirecionar_cadastro' } }];
